performance.script:
import { MemoryStore } from '<workspace>/plugins/personal-memory/lib/store.js'
const memory = new MemoryStore({ path: ':memory:', now: () => 100_000 })
const namespace = { mode: 'delivery', principalDigest: 'a'.repeat(64), principalRecordId: 'perf-owner', principalVersion: 1 }
const identity = { owner: 'user', scope: 'user-global' }
for (let i = 0; i < 1000; i++) memory.applyApprovedMutation({ op: 'add', namespace, identity, idempotencyKey: `record-${i}`, entry: {
  kind: 'experience', content: `Atlas recovery procedure ${i}`, sensitivity: 'private', trust: 'user-confirmed', confidence: 1,
  provenance: { source: 'synthetic-performance-fixture', observedAt: 1 },
  knowledge: { applicability: ['Applicable only after inspecting the current migration state.'], counterexamples: ['A prior deployment failed when the migration state was assumed.'], claim: { key: 'atlas.recovery.mode', value: `mode-${i}` } },
} })
const samples = []
for (let i = 0; i < 3; i++) {
  const started = performance.now()
  const snapshot = memory.snapshot({ context: { namespace, workspace: '/work/atlas', agentPreset: 'primary' }, query: 'Atlas recovery', limit: 1, maxBytes: 2048, maxTokens: 512 })
  if (!snapshot.text.includes('1000 records; bodies omitted by budget; no value selected.')) throw new Error('lost disagreement')
  samples.push(Number((performance.now() - started).toFixed(3)))
}
console.log(JSON.stringify({ records: 1000, samplesMs: samples, meanMs: samples.reduce((a, b) => a + b) / samples.length }))
memory.close()
